-- +goose Up
-- Kaapi Estate schema v1.
-- Conventions:
--   * money is bigint paise, never floating point
--   * stay dates are `date` in IST, timestamps are timestamptz
--   * ids are UUIDv7, generated by the application
--   * states are text + CHECK rather than Postgres enums, so adding a state is a one-line migration
--   * every invariant that protects money or inventory is enforced here, not only in Go

-- ---------------------------------------------------------------- property
CREATE TABLE property_settings (
    id                    smallint    PRIMARY KEY DEFAULT 1 CHECK (id = 1),
    name                  text        NOT NULL,
    timezone              text        NOT NULL DEFAULT 'Asia/Kolkata',
    currency              text        NOT NULL DEFAULT 'INR',
    check_in_time         time        NOT NULL,
    check_out_time        time        NOT NULL,
    hold_minutes          int         NOT NULL CHECK (hold_minutes BETWEEN 1 AND 60),
    max_nights            int         NOT NULL CHECK (max_nights BETWEEN 1 AND 60),
    max_rooms_per_booking int         NOT NULL CHECK (max_rooms_per_booking BETWEEN 1 AND 20),
    child_age_max         int         NOT NULL CHECK (child_age_max BETWEEN 0 AND 17),
    gst_slabs             jsonb       NOT NULL,   -- [{max_tariff_paise_per_night|null, rate_bps}]
    lane_rules            jsonb       NOT NULL,   -- {"ROOM":"RESERVATIONS", ...}
    updated_at            timestamptz NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------- identity
CREATE TABLE users (
    id            uuid        PRIMARY KEY,
    email         text        NOT NULL,
    name          text        NOT NULL,
    phone         text,
    role          text        NOT NULL CHECK (role IN ('GUEST', 'RESERVATIONS', 'SALES', 'GM', 'ADMIN')),
    password_hash text,
    is_active     boolean     NOT NULL DEFAULT true,
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now(),
    CHECK (role = 'GUEST' OR password_hash IS NOT NULL)   -- staff always sign in with a password
);
CREATE UNIQUE INDEX users_email_key ON users (lower(email));

CREATE TABLE sessions (
    id           uuid        PRIMARY KEY,
    user_id      uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    refresh_hash bytea       NOT NULL UNIQUE,
    user_agent   text,
    ip_hash      bytea,
    created_at   timestamptz NOT NULL DEFAULT now(),
    expires_at   timestamptz NOT NULL,
    revoked_at   timestamptz,
    replaced_by  uuid        REFERENCES sessions (id)   -- refresh rotation chain; reuse of a replaced token revokes the chain
);
CREATE INDEX sessions_user_idx ON sessions (user_id) WHERE revoked_at IS NULL;

CREATE TABLE otp_codes (
    id          uuid        PRIMARY KEY,
    email       text        NOT NULL,
    purpose     text        NOT NULL CHECK (purpose IN ('GUEST_LOGIN')),
    code_hash   bytea       NOT NULL,
    attempts    int         NOT NULL DEFAULT 0 CHECK (attempts BETWEEN 0 AND 10),
    created_at  timestamptz NOT NULL DEFAULT now(),
    expires_at  timestamptz NOT NULL,
    consumed_at timestamptz
);
CREATE INDEX otp_codes_email_idx ON otp_codes (lower(email), created_at DESC);

CREATE TABLE rate_limit_buckets (
    key          text        NOT NULL,
    window_start timestamptz NOT NULL,
    count        int         NOT NULL DEFAULT 0,
    PRIMARY KEY (key, window_start)
);

CREATE TABLE idempotency_keys (
    scope        text        NOT NULL,
    key          text        NOT NULL,
    request_hash bytea       NOT NULL,
    status_code  int,
    response     jsonb,
    created_at   timestamptz NOT NULL DEFAULT now(),
    expires_at   timestamptz NOT NULL,
    PRIMARY KEY (scope, key)
);

-- ---------------------------------------------------------------- catalogue
CREATE TABLE room_types (
    id                uuid        PRIMARY KEY,
    slug              text        NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
    name              text        NOT NULL,
    kind              text        NOT NULL CHECK (kind IN ('ROOM', 'VILLA')),
    total_keys        int         NOT NULL CHECK (total_keys > 0),
    size_sqm          int         NOT NULL CHECK (size_sqm > 0),
    bed               text        NOT NULL,
    view              text        NOT NULL,
    base_occupancy    int         NOT NULL CHECK (base_occupancy >= 1),
    max_adults        int         NOT NULL,
    max_children      int         NOT NULL CHECK (max_children >= 0),
    extra_adult_paise bigint      NOT NULL CHECK (extra_adult_paise >= 0),
    extra_child_paise bigint      NOT NULL CHECK (extra_child_paise >= 0),
    summary           text        NOT NULL,
    description       text        NOT NULL,
    amenities         text[]      NOT NULL DEFAULT '{}',
    sort              int         NOT NULL DEFAULT 0,
    is_active         boolean     NOT NULL DEFAULT true,
    created_at        timestamptz NOT NULL DEFAULT now(),
    updated_at        timestamptz NOT NULL DEFAULT now(),
    CHECK (max_adults >= base_occupancy)
);

CREATE TABLE room_type_photos (
    id            uuid PRIMARY KEY,
    room_type_id  uuid NOT NULL REFERENCES room_types (id) ON DELETE CASCADE,
    url           text NOT NULL,
    alt           text NOT NULL,
    width         int,
    height        int,
    blur_data_url text,
    sort          int  NOT NULL DEFAULT 0
);
CREATE INDEX room_type_photos_room_idx ON room_type_photos (room_type_id, sort);

CREATE TABLE rate_plans (
    id                  uuid        PRIMARY KEY,
    room_type_id        uuid        NOT NULL REFERENCES room_types (id) ON DELETE CASCADE,
    code                text        NOT NULL,
    name                text        NOT NULL,
    inclusions          text[]      NOT NULL DEFAULT '{}',
    refundable          boolean     NOT NULL,
    cancellation_policy text        NOT NULL CHECK (cancellation_policy IN ('FREE_UNTIL_7_DAYS', 'NON_REFUNDABLE')),
    min_nights          int         NOT NULL DEFAULT 1 CHECK (min_nights >= 1),
    -- how this plan derives from the room-only price, so admin edits cascade to every plan
    add_paise_per_night bigint      NOT NULL DEFAULT 0 CHECK (add_paise_per_night >= 0),
    discount_bps        int         NOT NULL DEFAULT 0 CHECK (discount_bps BETWEEN 0 AND 5000),
    sort                int         NOT NULL DEFAULT 0,
    is_active           boolean     NOT NULL DEFAULT true,
    created_at          timestamptz NOT NULL DEFAULT now(),
    UNIQUE (room_type_id, code)
);

-- ---------------------------------------------------------------- inventory and rates
-- One row per room type per night: what the website may sell.
-- The CHECK on sold <= allotment is the last line of defence against overbooking.
CREATE TABLE night_inventory (
    room_type_id        uuid        NOT NULL REFERENCES room_types (id) ON DELETE CASCADE,
    date                date        NOT NULL,
    allotment           int         NOT NULL CHECK (allotment >= 0),
    sold                int         NOT NULL DEFAULT 0 CHECK (sold >= 0),
    stop_sell           boolean     NOT NULL DEFAULT false,
    stop_sell_reason    text,
    min_stay            int         NOT NULL DEFAULT 1 CHECK (min_stay >= 1),
    closed_to_arrival   boolean     NOT NULL DEFAULT false,
    closed_to_departure boolean     NOT NULL DEFAULT false,
    updated_by          uuid        REFERENCES users (id),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (room_type_id, date),
    CONSTRAINT night_inventory_no_oversell CHECK (sold <= allotment)
);

CREATE TABLE night_rates (
    rate_plan_id uuid        NOT NULL REFERENCES rate_plans (id) ON DELETE CASCADE,
    date         date        NOT NULL,
    price_paise  bigint      NOT NULL CHECK (price_paise > 0),
    updated_by   uuid        REFERENCES users (id),
    updated_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (rate_plan_id, date)
);

CREATE TABLE promo_codes (
    id            uuid        PRIMARY KEY,
    code          text        NOT NULL CHECK (code ~ '^[A-Z0-9]{3,24}$'),
    type          text        NOT NULL CHECK (type IN ('PERCENT', 'FLAT')),
    value         bigint      NOT NULL CHECK (value > 0),   -- bps for PERCENT, paise for FLAT
    description   text        NOT NULL,
    stay_from     date        NOT NULL,
    stay_to       date        NOT NULL,
    book_from     date        NOT NULL,
    book_to       date        NOT NULL,
    min_nights    int         NOT NULL DEFAULT 1 CHECK (min_nights >= 1),
    max_uses      int         CHECK (max_uses > 0),
    used_count    int         NOT NULL DEFAULT 0 CHECK (used_count >= 0),
    room_type_ids uuid[],                                   -- NULL = every room type
    is_active     boolean     NOT NULL DEFAULT true,
    created_at    timestamptz NOT NULL DEFAULT now(),
    CHECK (type <> 'PERCENT' OR value <= 5000),
    CHECK (stay_to >= stay_from),
    CHECK (book_to >= book_from),
    CONSTRAINT promo_codes_no_overuse CHECK (max_uses IS NULL OR used_count <= max_uses)
);
CREATE UNIQUE INDEX promo_codes_code_key ON promo_codes (code);

-- ---------------------------------------------------------------- holds and bookings
-- A hold reserves rooms for a few minutes while the guest checks out.
-- Active holds are counted live (status = 'ACTIVE' AND expires_at > now()), so an expired
-- hold stops counting immediately, with no cron job involved.
CREATE TABLE holds (
    id              uuid        PRIMARY KEY,
    room_type_id    uuid        NOT NULL REFERENCES room_types (id),
    rate_plan_id    uuid        NOT NULL REFERENCES rate_plans (id),
    check_in        date        NOT NULL,
    check_out       date        NOT NULL,
    rooms           int         NOT NULL CHECK (rooms BETWEEN 1 AND 20),
    adults          int         NOT NULL CHECK (adults >= 1),
    children        int         NOT NULL DEFAULT 0 CHECK (children >= 0),
    hold_token_hash bytea       NOT NULL,
    quote           jsonb       NOT NULL,   -- frozen price breakdown shown to the guest
    promo_code_id   uuid        REFERENCES promo_codes (id),
    status          text        NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'CONVERTED', 'RELEASED', 'EXPIRED')),
    expires_at      timestamptz NOT NULL,
    created_at      timestamptz NOT NULL DEFAULT now(),
    CHECK (check_out > check_in)
);
CREATE INDEX holds_active_idx ON holds (room_type_id, check_in, check_out) WHERE status = 'ACTIVE';

CREATE TABLE bookings (
    id               uuid        PRIMARY KEY,
    ref              text        NOT NULL UNIQUE CHECK (ref ~ '^KS-[2-9A-HJ-NP-Z]{6}$'),
    hold_id          uuid        UNIQUE REFERENCES holds (id),   -- NULL only for imported or seeded bookings
    guest_user_id    uuid        REFERENCES users (id),
    guest_name       text        NOT NULL,
    guest_email      text        NOT NULL,
    guest_phone      text        NOT NULL,
    guest_country    text        NOT NULL CHECK (guest_country ~ '^[A-Z]{2}$'),
    adults           int         NOT NULL CHECK (adults >= 1),
    children         int         NOT NULL DEFAULT 0 CHECK (children >= 0),
    rooms            int         NOT NULL CHECK (rooms >= 1),
    room_type_id     uuid        NOT NULL REFERENCES room_types (id),
    rate_plan_id     uuid        NOT NULL REFERENCES rate_plans (id),
    check_in         date        NOT NULL,
    check_out        date        NOT NULL,
    nights           int         GENERATED ALWAYS AS (check_out - check_in) STORED,
    arrival_window   text,
    special_requests text,
    status           text        NOT NULL CHECK (status IN ('PENDING_PAYMENT', 'CONFIRMED', 'PAYMENT_FAILED', 'EXPIRED', 'CANCELLED', 'REFUND_PENDING', 'REFUNDED')),
    subtotal_paise   bigint      NOT NULL CHECK (subtotal_paise >= 0),
    discount_paise   bigint      NOT NULL DEFAULT 0 CHECK (discount_paise >= 0),
    tax_paise        bigint      NOT NULL CHECK (tax_paise >= 0),
    total_paise      bigint      NOT NULL CHECK (total_paise >= 0),
    price_breakdown  jsonb       NOT NULL,
    promo_code_id    uuid        REFERENCES promo_codes (id),
    consent_version  text        NOT NULL,
    consent_at       timestamptz NOT NULL,
    marketing_opt_in boolean     NOT NULL DEFAULT false,
    source           text        NOT NULL DEFAULT 'DIRECT_WEB',
    created_at       timestamptz NOT NULL DEFAULT now(),
    updated_at       timestamptz NOT NULL DEFAULT now(),
    confirmed_at     timestamptz,
    cancelled_at     timestamptz,
    exported_at      timestamptz,
    CHECK (check_out > check_in),
    CONSTRAINT bookings_total_adds_up CHECK (total_paise = subtotal_paise - discount_paise + tax_paise)
);
CREATE INDEX bookings_status_checkin_idx ON bookings (status, check_in);
CREATE INDEX bookings_guest_email_idx ON bookings (lower(guest_email));

-- One row per booked night: lets us prove that night_inventory.sold matches real bookings.
CREATE TABLE booking_nights (
    booking_id   uuid NOT NULL REFERENCES bookings (id) ON DELETE CASCADE,
    date         date NOT NULL,
    room_type_id uuid NOT NULL REFERENCES room_types (id),
    rooms        int  NOT NULL CHECK (rooms >= 1),
    PRIMARY KEY (booking_id, date)
);
CREATE INDEX booking_nights_room_date_idx ON booking_nights (room_type_id, date);

CREATE TABLE payments (
    id                  uuid        PRIMARY KEY,
    booking_id          uuid        NOT NULL REFERENCES bookings (id),
    provider            text        NOT NULL,
    provider_order_id   text        NOT NULL UNIQUE,
    provider_payment_id text,
    amount_paise        bigint      NOT NULL CHECK (amount_paise > 0),
    status              text        NOT NULL CHECK (status IN ('CREATED', 'CAPTURED', 'FAILED', 'REFUND_PENDING', 'REFUNDED')),
    idempotency_key     text        NOT NULL UNIQUE,
    failure_reason      text,
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX payments_booking_idx ON payments (booking_id);

-- Webhook inbox: the unique key makes a duplicate delivery a no-op.
CREATE TABLE payment_events (
    id                uuid        PRIMARY KEY,
    provider          text        NOT NULL,
    provider_event_id text        NOT NULL,
    type              text        NOT NULL,
    payload           jsonb       NOT NULL,
    signature_valid   boolean     NOT NULL,
    received_at       timestamptz NOT NULL DEFAULT now(),
    processed_at      timestamptz,
    UNIQUE (provider, provider_event_id)
);

-- ---------------------------------------------------------------- enquiries and AI
CREATE TABLE enquiries (
    id                 uuid         PRIMARY KEY,
    ref                text         NOT NULL UNIQUE CHECK (ref ~ '^ENQ-[0-9]{4,}$'),
    channel            text         NOT NULL CHECK (channel IN ('WEB_FORM', 'EMAIL', 'WHATSAPP', 'EVENT_FORM')),
    sender_name        text,
    sender_email       text,
    sender_phone       text,
    subject            text,
    raw_text           text         NOT NULL CHECK (length(raw_text) BETWEEN 1 AND 5000),
    received_at        timestamptz  NOT NULL DEFAULT now(),
    dedupe_hash        bytea        NOT NULL,
    language           text,
    category           text         CHECK (category IN ('ROOM', 'WEDDING', 'OFFSITE', 'COMPLAINT', 'OTHER')),
    secondary_category text         CHECK (secondary_category IN ('ROOM', 'WEDDING', 'OFFSITE', 'COMPLAINT', 'OTHER')),
    confidence         numeric(4,3) CHECK (confidence BETWEEN 0 AND 1),
    extracted          jsonb        NOT NULL DEFAULT '{}',
    summary            text,
    lane               text         NOT NULL DEFAULT 'UNSORTED' CHECK (lane IN ('RESERVATIONS', 'SALES', 'GM', 'UNSORTED')),
    assigned_user_id   uuid         REFERENCES users (id),
    priority           text         NOT NULL DEFAULT 'NORMAL' CHECK (priority IN ('NORMAL', 'HIGH')),
    status             text         NOT NULL DEFAULT 'NEW' CHECK (status IN ('NEW', 'IN_PROGRESS', 'REPLIED', 'CLOSED', 'SPAM')),
    routed_by          text         CHECK (routed_by IN ('AI', 'RULE', 'HUMAN')),
    ai_status          text         NOT NULL DEFAULT 'PENDING' CHECK (ai_status IN ('PENDING', 'DONE', 'FALLBACK', 'FAILED')),
    ai_model           text,
    prompt_version     text,
    ai_latency_ms      int,
    first_response_at  timestamptz,
    linked_booking_id  uuid         REFERENCES bookings (id),
    created_at         timestamptz  NOT NULL DEFAULT now(),
    updated_at         timestamptz  NOT NULL DEFAULT now(),
    CHECK (sender_email IS NOT NULL OR sender_phone IS NOT NULL)
);
CREATE INDEX enquiries_lane_idx ON enquiries (lane, status, received_at DESC);
CREATE INDEX enquiries_dedupe_idx ON enquiries (dedupe_hash);

-- Every classification, re-route, edit and send. Feeds the audit trail and the AI-vs-human accuracy numbers.
CREATE TABLE enquiry_events (
    id            uuid        PRIMARY KEY,
    enquiry_id    uuid        NOT NULL REFERENCES enquiries (id) ON DELETE CASCADE,
    type          text        NOT NULL CHECK (type IN ('RECEIVED', 'CLASSIFIED', 'REROUTED', 'CATEGORY_CHANGED', 'FIELDS_CORRECTED', 'ASSIGNED', 'DRAFT_CREATED', 'DRAFT_EDITED', 'SENT', 'ALERTED', 'CLOSED')),
    actor         text        NOT NULL CHECK (actor IN ('AI', 'SYSTEM', 'USER')),
    actor_user_id uuid        REFERENCES users (id),
    from_value    jsonb,
    to_value      jsonb,
    created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX enquiry_events_enquiry_idx ON enquiry_events (enquiry_id, created_at);

CREATE TABLE enquiry_drafts (
    id             uuid        PRIMARY KEY,
    enquiry_id     uuid        NOT NULL REFERENCES enquiries (id) ON DELETE CASCADE,
    version        int         NOT NULL CHECK (version >= 1),
    body_template  text        NOT NULL,   -- AI prose with {{QUOTE}}-style placeholders
    body_rendered  text        NOT NULL,   -- placeholders filled by the server from live rates
    quote          jsonb,
    author         text        NOT NULL CHECK (author IN ('AI', 'USER')),
    author_user_id uuid        REFERENCES users (id),
    flagged_reason text,                   -- e.g. the AI wrote a price of its own and it was stripped
    created_at     timestamptz NOT NULL DEFAULT now(),
    sent_at        timestamptz,
    sent_by        uuid        REFERENCES users (id),
    UNIQUE (enquiry_id, version)
);

CREATE TABLE kb_facts (
    id         uuid        PRIMARY KEY,
    key        text        NOT NULL UNIQUE,
    category   text        NOT NULL,
    question   text        NOT NULL,
    answer     text        NOT NULL,
    is_active  boolean     NOT NULL DEFAULT true,
    updated_by uuid        REFERENCES users (id),
    updated_at timestamptz NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------- operations
CREATE TABLE notifications (
    id                uuid        PRIMARY KEY,
    recipient_role    text        CHECK (recipient_role IN ('RESERVATIONS', 'SALES', 'GM', 'ADMIN')),
    recipient_user_id uuid        REFERENCES users (id),
    type              text        NOT NULL CHECK (type IN ('COMPLAINT_ALERT', 'UNSORTED', 'BOOKING', 'REFUND_NEEDED')),
    enquiry_id        uuid        REFERENCES enquiries (id) ON DELETE CASCADE,
    booking_id        uuid        REFERENCES bookings (id) ON DELETE CASCADE,
    body              text        NOT NULL,
    created_at        timestamptz NOT NULL DEFAULT now(),
    read_at           timestamptz,
    CHECK (recipient_role IS NOT NULL OR recipient_user_id IS NOT NULL)
);
CREATE INDEX notifications_unread_idx ON notifications (recipient_role, created_at DESC) WHERE read_at IS NULL;

-- Every message the system "sends" lands here. Channels are simulated in this build.
CREATE TABLE outbox_messages (
    id         uuid        PRIMARY KEY,
    channel    text        NOT NULL CHECK (channel IN ('EMAIL', 'WHATSAPP', 'SMS')),
    kind       text        NOT NULL CHECK (kind IN ('OTP', 'BOOKING_CONFIRMATION', 'ENQUIRY_REPLY', 'ALERT', 'REFUND_NOTICE')),
    recipient  text        NOT NULL,
    subject    text,
    body       text        NOT NULL,
    enquiry_id uuid        REFERENCES enquiries (id) ON DELETE SET NULL,
    booking_id uuid        REFERENCES bookings (id) ON DELETE SET NULL,
    sent_by    uuid        REFERENCES users (id),
    status     text        NOT NULL DEFAULT 'SIMULATED' CHECK (status IN ('SIMULATED', 'SENT', 'FAILED')),
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX outbox_messages_created_idx ON outbox_messages (created_at DESC);

CREATE TABLE audit_logs (
    id            uuid        PRIMARY KEY,
    actor_user_id uuid        REFERENCES users (id),
    action        text        NOT NULL,
    entity        text        NOT NULL,
    entity_id     text        NOT NULL,
    before        jsonb,
    after         jsonb,
    ip_hash       bytea,
    created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX audit_logs_entity_idx ON audit_logs (entity, entity_id, created_at DESC);

-- +goose Down
DROP TABLE IF EXISTS audit_logs;
DROP TABLE IF EXISTS outbox_messages;
DROP TABLE IF EXISTS notifications;
DROP TABLE IF EXISTS kb_facts;
DROP TABLE IF EXISTS enquiry_drafts;
DROP TABLE IF EXISTS enquiry_events;
DROP TABLE IF EXISTS enquiries;
DROP TABLE IF EXISTS payment_events;
DROP TABLE IF EXISTS payments;
DROP TABLE IF EXISTS booking_nights;
DROP TABLE IF EXISTS bookings;
DROP TABLE IF EXISTS holds;
DROP TABLE IF EXISTS promo_codes;
DROP TABLE IF EXISTS night_rates;
DROP TABLE IF EXISTS night_inventory;
DROP TABLE IF EXISTS rate_plans;
DROP TABLE IF EXISTS room_type_photos;
DROP TABLE IF EXISTS room_types;
DROP TABLE IF EXISTS idempotency_keys;
DROP TABLE IF EXISTS rate_limit_buckets;
DROP TABLE IF EXISTS otp_codes;
DROP TABLE IF EXISTS sessions;
DROP TABLE IF EXISTS users;
DROP TABLE IF EXISTS property_settings;
